// Auto-generated library image data embedded as base64 to ensure
// instant loading even before a full app rebuild / reinstall.
import 'dart:convert';
import 'dart:typed_data';

class WhiteboardLibraryData {
  static const String topic_movie_book_tvBase64 = '';

  static const String topic_kindest_thingBase64 = '';

  static const String topic_live_anywhereBase64 = '';

  static const String topic_society_improvingBase64 = '';

  static const String topic_start_life_overBase64 = '';

  static Uint8List getBytes(String key) {
    final b64 = switch (key) {
      'topic_movie_book_tv' => topic_movie_book_tvBase64,
      'topic_kindest_thing' => topic_kindest_thingBase64,
      'topic_live_anywhere' => topic_live_anywhereBase64,
      'topic_society_improving' => topic_society_improvingBase64,
      'topic_start_life_over' => topic_start_life_overBase64,
      _ => '',
    };
    if (b64.isEmpty) return Uint8List(0);
    return base64Decode(b64);
  }
}
